{
  "tecnicas": [
    {
      "tecnica": "Apelación a la autoridad y al prestigio",
      "autor": "Edward Bernays",
      "obra": "Propaganda",
      "año": "1928",
      "cita_breve": "La propaganda aprovecha la confianza en figuras “autorizadas” para orientar la opinión pública y legitimar mensajes."
    },
    {
      "tecnica": "Culpabilización indirecta",
      "autor": "Erich Fromm",
      "obra": "Escape from Freedom",
      "año": "1941",
      "cita_breve": "Los mecanismos sociales pueden conducir a responsabilizar a otros o desplazar la culpa para aliviar la ansiedad."
    },
    {
      "tecnica": "Culpabilización",
      "autor": "Gustave Le Bon",
      "obra": "Psicología de las masas",
      "año": "1895",
      "cita_breve": "En la dinámica de masas, la emoción y la sugestión facilitan atribuir culpa y orientar la condena hacia un “culpable” o grupo."
    },
    {
      "tecnica": "Miedo (fear appeal)",
      "autor": "Amos Tversky y Daniel Kahneman",
      "obra": "Judgment Under Uncertainty: Heuristics and Biases",
      "año": "1974",
      "cita_breve": "Las percepciones de riesgo y amenaza se procesan con heurísticas; los mensajes que enfatizan consecuencias pueden sesgar la evaluación."
    },
    {
      "tecnica": "Culpabilización política",
      "autor": "Noam Chomsky",
      "obra": "Manufacturing Consent: The Political Economy of the Mass Media (con Edward S. Herman)",
      "año": "1988",
      "cita_breve": "Los medios y la propaganda pueden enmarcar problemas políticos de forma que ciertos actores o grupos queden responsabilizados para justificar políticas."
    }
  ]
}
